import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.DnrXFDHb.js";const C=JSON.parse('{"title":"快速开始","description":"从安装 ChatGPT 到配置完成的任务步骤一览：每一步干什么、大约多久、完成标志是什么、卡住了去哪查。","frontmatter":{"title":"快速开始","description":"从安装 ChatGPT 到配置完成的任务步骤一览：每一步干什么、大约多久、完成标志是什么、卡住了去哪查。"},"headers":[],"relativePath":"guide/quickstart.md","filePath":"guide/quickstart.md","lastUpdated":null}'),d={name:"guide/quickstart.md"};function h(i,t,s,n,c,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>这一页是<strong>全部任务步骤的总览</strong>。从安装到用上 ChatGPT，一共 6 步，大约 20 分钟。先把每一步是什么、怎么算完成看清楚，再一步步点进详细教程去做，心里就有底了。</p><h2 id="全部步骤一览" tabindex="-1">全部步骤一览 <a class="header-anchor" href="#全部步骤一览" aria-label="Permalink to &quot;全部步骤一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>干什么</th><th>大约多久</th><th>完成标志</th></tr></thead><tbody><tr><td><a href="#第-1-步安装-chatgpt-桌面应用含-codex">1. 安装桌面应用</a></td><td>装好 ChatGPT 桌面应用（里面自带 Codex）</td><td>2 分钟</td><td>应用能正常打开</td></tr><tr><td><a href="#第-2-步注册-ccws-账号">2. 注册 CCWS 账号</a></td><td>在 CCWS 官网注册并登录</td><td>2 分钟</td><td>能进入控制台</td></tr><tr><td><a href="#第-3-步充值">3. 充值</a></td><td>在钱包页面充钱</td><td>3 分钟</td><td>余额大于 0</td></tr><tr><td><a href="#第-4-步创建-api-key">4. 创建 API Key</a></td><td>在控制台生成一串 <code>sk-</code> 开头的 Key</td><td>2 分钟</td><td>复制到了一串 Key</td></tr><tr><td><a href="#第-5-步配置-chatgpt-连接-ccws">5. 配置 ChatGPT 连接 CCWS</a></td><td>用 CC Switch 填入地址和 Key</td><td>5 分钟</td><td><strong>ChatGPT 能正常回复你 = 全部完成</strong></td></tr><tr><td><a href="#第-6-步生图功能可选">6. 生图功能（可选）</a></td><td>配置生图能力</td><td>15-30 分钟</td><td>想用的时候再看</td></tr></tbody></table><p>第 1～5 步必须按顺序做，第 6 步可做可不做。</p><hr><h2 id="第-1-步-安装-chatgpt-桌面应用-含-codex" tabindex="-1">第 1 步：安装 ChatGPT 桌面应用（含 Codex） <a class="header-anchor" href="#第-1-步-安装-chatgpt-桌面应用-含-codex" aria-label="Permalink to &quot;第 1 步：安装 ChatGPT 桌面应用（含 Codex）&quot;">​</a></h2><p><strong>干什么</strong>：在电脑上装好 ChatGPT 桌面应用。Codex（AI 编程工具，你说话、它写代码）就在这个应用里，不用单独装。</p><p><strong>✅ 完成标志</strong>：应用能正常打开，能看到主界面。</p><p>👉 详细教程：<a href="/guide/codex-install">安装 ChatGPT</a> 🔧 卡住了：<a href="/troubleshooting/">疑难解答总览</a></p><h2 id="第-2-步-注册-ccws-账号" tabindex="-1">第 2 步：注册 CCWS 账号 <a class="header-anchor" href="#第-2-步-注册-ccws-账号" aria-label="Permalink to &quot;第 2 步：注册 CCWS 账号&quot;">​</a></h2><p><strong>干什么</strong>：在 CCWS 官网注册账号并登录。CCWS 是给 ChatGPT 提供联网服务的平台，后面几步都在这上面操作。</p><p><strong>✅ 完成标志</strong>：能进入控制台（管理账号的网页后台）。</p><p>👉 详细教程：<a href="/guide/register">注册 / 登录</a></p><h2 id="第-3-步-充值" tabindex="-1">第 3 步：充值 <a class="header-anchor" href="#第-3-步-充值" aria-label="Permalink to &quot;第 3 步：充值&quot;">​</a></h2><p><strong>干什么</strong>：在控制台的钱包页面充钱。ChatGPT 每次干活都会消耗余额，先充好钱后面才调得通。</p><p><strong>✅ 完成标志</strong>：钱包余额大于 0。</p><p>👉 详细教程：<a href="/guide/recharge">充值 / 续费</a> 🔧 卡住了：<a href="/guide/recharge#付了钱没到账">付了钱没到账？</a></p><h2 id="第-4-步-创建-api-key" tabindex="-1">第 4 步：创建 API Key <a class="header-anchor" href="#第-4-步-创建-api-key" aria-label="Permalink to &quot;第 4 步：创建 API Key&quot;">​</a></h2><p><strong>干什么</strong>：在控制台生成一串 API Key（读作&quot;A-P-I-Key&quot;，相当于一串密码，用来证明你有权限用 CCWS 的服务）。第 5 步配置时要用它。</p><p><strong>✅ 完成标志</strong>：复制到了一串以 <code>sk-</code> 开头的 Key。</p><p>👉 详细教程：<a href="/guide/api-key">创建 API Key</a></p><h2 id="第-5-步-配置-chatgpt-连接-ccws" tabindex="-1">第 5 步：配置 ChatGPT 连接 CCWS <a class="header-anchor" href="#第-5-步-配置-chatgpt-连接-ccws" aria-label="Permalink to &quot;第 5 步：配置 ChatGPT 连接 CCWS&quot;">​</a></h2><p><strong>干什么</strong>：用一个叫 CC Switch 的小工具（有界面、能点鼠标），把 CCWS 的请求地址和 API Key 填进 ChatGPT。这是最关键的一步。</p><p><strong>🎉 完成标志</strong>：给 ChatGPT 发一条测试消息，它能正常回复你。<strong>看到它回复，就说明全部配置完成了</strong>，可以开始用了。</p><p>👉 详细教程：<a href="/guide/connect">配置 ChatGPT 连接 CCWS</a> 🔧 卡住了：<a href="/troubleshooting/network">网络与连接排查</a></p><p>💡 <strong>顺手了解（可选）</strong>：CC Switch 不只用来配 CCWS，还能管多个账号、多个服务之间切换配置：<a href="/guide/config-switch">CC Switch 使用教程</a>。</p><h2 id="第-6-步-生图功能-可选" tabindex="-1">第 6 步：生图功能（可选） <a class="header-anchor" href="#第-6-步-生图功能-可选" aria-label="Permalink to &quot;第 6 步：生图功能（可选）&quot;">​</a></h2><p><strong>干什么</strong>：让 ChatGPT 生成、编辑图片，比如&quot;帮我生成一张产品宣传图&quot;&quot;把这张图改成某种风格&quot;。</p><p><strong>✅ 完成标志</strong>：发一个生图任务，ChatGPT 能生成图片。</p><p>👉 详细教程：<a href="/guide/codex-image">ChatGPT 生图教程</a></p><blockquote><p>生图不是必须的，先把第 1～5 步跑通再说。</p></blockquote><hr><h2 id="全部完成怎么确认" tabindex="-1">全部完成怎么确认 <a class="header-anchor" href="#全部完成怎么确认" aria-label="Permalink to &quot;全部完成怎么确认&quot;">​</a></h2><p>对照这张表，全部打勾就是完成了：</p><ul><li>✅ 应用能正常打开</li><li>✅ 能进入控制台</li><li>✅ 钱包余额大于 0</li><li>✅ 复制到了一串 <code>sk-</code> 开头的 Key</li><li>✅ ChatGPT 能正常回复你的测试消息</li></ul><p>前面 4 项是准备材料，最后一项是验收。<strong>看到 ChatGPT 回复你，就可以开始用了</strong>，之后遇到问题随时去 <a href="/troubleshooting/">疑难解答总览</a> 按症状查。</p>',37)])])}const g=a(d,[["render",h]]);export{C as __pageData,g as default};
